// Some portions generated by Codex
package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.junit.jupiter.api.Test;

class MemoryPreparedInputRepresentativeRouteTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = VF.createIRI("urn:prepared-input:subject");
	private static final IRI PREDICATE = VF.createIRI("urn:prepared-input:predicate");
	private static final Literal STORED = VF.createLiteral("label", "en");
	private static final Literal REQUEST = VF.createLiteral("label", "EN");
	private static final String PREFIX = "PREFIX : <urn:prepared-input:> ";

	@Test
	void publicInitialBindingFilterMatchesTheSourceReturnedRepresentative() {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try {
			try (var connection = repository.getConnection()) {
				connection.add(SUBJECT, PREDICATE, STORED);
				List<Statement> readback = new ArrayList<>();
				try (var statements = connection.getStatements(SUBJECT, PREDICATE, null, false)) {
					while (statements.hasNext()) {
						readback.add(statements.next());
					}
				}
				assertThat(readback).singleElement().satisfies(statement -> {
					assertThat(statement.getObject()).isInstanceOf(Literal.class);
					assertThat(((Literal) statement.getObject()).getLanguage()).contains("en");
				});
			}

			List<BindingSet> unfiltered = evaluate(repository, "SELECT ?x WHERE { ?s :predicate ?x }");
			assertThat(unfiltered).hasSize(1);
			Value returned = unfiltered.getFirst().getValue("x");
			assertThat(returned).isInstanceOf(Literal.class);
			String returnedLanguage = ((Literal) returned).getLanguage().orElse(null);
			assertThat(returnedLanguage)
					.as("the public prepared query retains the API representative after the source readback")
					.isEqualTo("EN");

			List<BindingSet> filtered = evaluate(repository,
					"SELECT ?x WHERE { ?s :predicate ?x FILTER(LANG(?x) = \"EN\") }");
			assertThat(filtered).as("the filter must inspect the value returned by the real source: %s", returned)
					.hasSize(1);
			assertThat(filtered.getFirst().getValue("x")).isSameAs(returned);
		} finally {
			repository.shutDown();
		}
	}

	private static List<BindingSet> evaluate(SailRepository repository, String queryText) {
		try (var connection = repository.getConnection()) {
			TupleQuery query = connection.prepareTupleQuery(QueryLanguage.SPARQL, PREFIX + queryText);
			query.setBinding("x", REQUEST);
			try (var result = query.evaluate()) {
				List<BindingSet> rows = new ArrayList<>();
				while (result.hasNext()) {
					rows.add(result.next());
				}
				return rows;
			}
		}
	}
}
